// Read config values from Global Configuration node
const configNode = $('Global Configuration').first().json;
const config = {
  TEST_MODE: configNode.TEST_MODE === 'true' || configNode.TEST_MODE === true,
  TEST_EMAIL: configNode.TEST_EMAIL || 'saitarrunpitta@gmail.com',
  MAX_EMAILS_PER_RUN: parseInt(configNode.MAX_EMAILS_PER_RUN || '15', 10),
  DELAY_BETWEEN_EMAILS_SECONDS: parseInt(configNode.DELAY_BETWEEN_EMAILS_SECONDS || '90', 10),
  FOLLOW_UP_1_DAYS: parseInt(configNode.FOLLOW_UP_1_DAYS || '5', 10),
  MAX_RECRUITERS_PER_COMPANY_PER_DAY: parseInt(configNode.MAX_RECRUITERS_PER_COMPANY_PER_DAY || '2', 10)
};

const allRows = $input.all();
const validRecruiters = [];
const companyCountMap = {};

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const terminalStatuses = ['Replied', 'Interview', 'Closed', 'Do Not Contact', 'Failed'];

for (const item of allRows) {
  const row = item.json;

  const recruiterId = String(row.RecruiterID || '').trim();
  const firstName = String(row.FirstName || '').trim();
  const lastName = String(row.LastName || '').trim();
  const company = String(row.Company || '').trim();
  const rawEmail = String(row.Email || '').trim().toLowerCase();
  const status = String(row.Status || 'Pending').trim();
  const jobTitle = String(row.JobTitle || '').trim();
  const jobLink = String(row.JobLink || '').trim();
  const companyFocus = String(row.CompanyFocus || '').trim();
  const followUpCount = parseInt(row.FollowUpCount || '0', 10);
  const existingMessageId = String(row.GmailMessageID || '').trim();

  // 1. Status Filter
  if (terminalStatuses.includes(status)) continue;
  if (status !== 'Pending' && status !== 'Ready') continue;

  // 2. Duplicate / Idempotency Check
  if (existingMessageId !== '' || followUpCount > 0 || status === 'Sent') continue;

  // 3. Field & Email Validation
  if (!firstName || !company || !rawEmail) continue;
  if (!emailRegex.test(rawEmail)) continue;

  // 4. Company Daily Limit Check
  const compKey = company.toLowerCase();
  companyCountMap[compKey] = (companyCountMap[compKey] || 0) + 1;
  if (companyCountMap[compKey] > config.MAX_RECRUITERS_PER_COMPANY_PER_DAY) continue;

  // 5. Dynamic Subject Line
  let subject = `Software Engineering Opportunities at ${company} — Sai Tarrun Pitta`;
  if (jobTitle) {
    if (jobLink || (row.Notes && String(row.Notes).toLowerCase().includes('applied'))) {
      subject = `Application Follow-Up: ${jobTitle} — Sai Tarrun Pitta`;
    } else {
      subject = `${jobTitle} Opportunities at ${company} — Sai Tarrun Pitta`;
    }
  }

  // 6. Dynamic Personalized Sentence
  let personalizedSentence = '';
  if (companyFocus) {
    personalizedSentence = `I'm particularly interested in ${company} because of the work your teams are doing in ${companyFocus}, which aligns closely with my experience and interests.`;
  } else if (jobTitle) {
    personalizedSentence = `I also noticed the ${jobTitle} opportunity and believe my background aligns well with the engineering requirements of the role.`;
  }

  // 7. Plain Text Body
  const plainTextBody = `Hi ${firstName},

I hope you're doing well.

My name is Sai Tarrun Pitta, and I'm a Software Engineer with experience across backend engineering, full-stack development, distributed systems, cloud infrastructure, and AI-powered applications.

I've previously worked with Uber, Pacific Life, Cognizant, and California State University, Fullerton, contributing to production systems across scalable backend services, full-stack applications, distributed systems, cloud infrastructure, AI/LLM workflows, RAG systems, and agent-based applications.

My technical background includes Python, Java, TypeScript, JavaScript, React, FastAPI, Spring Boot, AWS, PostgreSQL, Redis, Docker, Kubernetes, LangChain, RAG, LLMs, AI Agents, APIs, microservices, and distributed systems.

I'm currently exploring Software Engineering opportunities at ${company}.

${personalizedSentence ? personalizedSentence + '\n\n' : ''}If there are any current or upcoming positions that align with my background, I would greatly appreciate it if you could review my profile and consider me for the interview process. If another recruiter or hiring manager is responsible for relevant engineering roles, I would also appreciate it if you could forward my profile or connect me with the appropriate person.

I've attached my resume for reference.

Thank you for your time and consideration.

Best regards,

Sai Tarrun Pitta
Email: saitarrunpitta@gmail.com
LinkedIn: linkedin.com/in/saitarrunpitta
GitHub: github.com/saitarrun
Portfolio: saitarrunpitta.vercel.app`;

  // 8. Clean, Mobile-Friendly HTML Email
  const htmlBody = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 15px; line-height: 1.6; color: #222222; margin: 0; padding: 0; }
    p { margin: 0 0 16px 0; }
    a { color: #0066cc; text-decoration: none; }
    a:hover { text-decoration: underline; }
    .signature { margin-top: 24px; border-top: 1px solid #e0e0e0; padding-top: 12px; font-size: 14px; color: #444444; }
  </style>
</head>
<body>
  <p>Hi ${firstName},</p>
  <p>I hope you're doing well.</p>
  <p>My name is <strong>Sai Tarrun Pitta</strong>, and I'm a Software Engineer with experience across backend engineering, full-stack development, distributed systems, cloud infrastructure, and AI-powered applications.</p>
  <p>I've previously worked with <strong>Uber</strong>, <strong>Pacific Life</strong>, <strong>Cognizant</strong>, and <strong>California State University, Fullerton</strong>, contributing to production systems across scalable backend services, full-stack applications, distributed systems, cloud infrastructure, AI/LLM workflows, RAG systems, and agent-based applications.</p>
  <p>My technical background includes Python, Java, TypeScript, JavaScript, React, FastAPI, Spring Boot, AWS, PostgreSQL, Redis, Docker, Kubernetes, LangChain, RAG, LLMs, AI Agents, APIs, microservices, and distributed systems.</p>
  <p>I'm currently exploring Software Engineering opportunities at <strong>${company}</strong>.</p>
  ${personalizedSentence ? `<p>${personalizedSentence}</p>` : ''}
  <p>If there are any current or upcoming positions that align with my background, I would greatly appreciate it if you could review my profile and consider me for the interview process. If another recruiter or hiring manager is responsible for relevant engineering roles, I would also appreciate it if you could forward my profile or connect me with the appropriate person.</p>
  <p>I've attached my resume for reference.</p>
  <p>Thank you for your time and consideration.</p>
  <p>Best regards,</p>
  <div class="signature">
    <strong>Sai Tarrun Pitta</strong><br>
    Email: <a href="mailto:saitarrunpitta@gmail.com">saitarrunpitta@gmail.com</a><br>
    LinkedIn: <a href="https://linkedin.com/in/saitarrunpitta" target="_blank">linkedin.com/in/saitarrunpitta</a><br>
    GitHub: <a href="https://github.com/saitarrun" target="_blank">github.com/saitarrun</a><br>
    Portfolio: <a href="https://saitarrunpitta.vercel.app" target="_blank">saitarrunpitta.vercel.app</a>
  </div>
</body>
</html>`;

  // Destination Routing
  const targetEmail = config.TEST_MODE ? config.TEST_EMAIL : rawEmail;
  const emailSubject = config.TEST_MODE ? `[TEST MODE - To: ${rawEmail}] ${subject}` : subject;

  validRecruiters.push({
    json: {
      ...row,
      RecruiterID: recruiterId,
      FirstName: firstName,
      LastName: lastName,
      Company: company,
      Email: rawEmail,
      OriginalRecipient: rawEmail,
      TargetEmail: targetEmail,
      Subject: emailSubject,
      HtmlBody: htmlBody,
      PlainTextBody: plainTextBody,
      ConfigTestMode: config.TEST_MODE,
      DelaySeconds: config.DELAY_BETWEEN_EMAILS_SECONDS,
      FollowUpDays: config.FOLLOW_UP_1_DAYS
    }
  });

  if (validRecruiters.length >= config.MAX_EMAILS_PER_RUN) break;
}

return validRecruiters;

const item = $input.first();
try {
  const resumeNode = $('Read Resume PDF').first();
  const binaryData = resumeNode && resumeNode.binary ? (resumeNode.binary.data || resumeNode.binary.resume) : null;
  if (binaryData) {
    item.binary = {
      resume: binaryData
    };
  }
} catch (e) {
  // Gracefully catch
}
return item;

const gmailResult = $input.first().json;
const recruiter = $('Attach Binary Resume').first().json;

const now = new Date();
const nowIso = now.toISOString();

// Calculate FollowUpDate = now + FollowUpDays (e.g. 5 days)
const followUpDays = parseInt(recruiter.FollowUpDays || '5', 10);
const followUpDate = new Date(now.getTime() + followUpDays * 24 * 60 * 60 * 1000);
const followUpIso = followUpDate.toISOString().split('T')[0];

return {
  json: {
    RecruiterID: recruiter.RecruiterID,
    FirstName: recruiter.FirstName,
    LastName: recruiter.LastName,
    Company: recruiter.Company,
    Email: recruiter.Email,
    Status: 'Sent',
    SentDate: nowIso,
    LastEmailDate: nowIso,
    FollowUpDate: followUpIso,
    FollowUpCount: 0,
    ReplyStatus: 'No Reply',
    GmailMessageID: gmailResult.id,
    GmailThreadID: gmailResult.threadId,
    Notes: recruiter.Notes || '',
    DelaySeconds: recruiter.DelaySeconds || 90
  }
};

const errorInfo = $input.first().json;
const recruiter = $('Attach Binary Resume').first().json;

const now = new Date();
const nowStr = now.toISOString().replace('T', ' ').substring(0, 16);
const errorMsg = errorInfo.error ? errorInfo.error.message : 'Unknown Gmail error';

const existingNotes = recruiter.Notes ? recruiter.Notes + '\n' : '';
const updatedNotes = `${existingNotes}[${nowStr}] Gmail send failed: ${errorMsg}`;

return {
  json: {
    RecruiterID: recruiter.RecruiterID,
    FirstName: recruiter.FirstName,
    LastName: recruiter.LastName,
    Company: recruiter.Company,
    Email: recruiter.Email,
    Status: 'Failed',
    Notes: updatedNotes,
    Error: errorMsg
  }
};
